//! Node of the circular doubly-linked list the ear-clipping triangulator walks.
//!
//! The reference implementation links heap-allocated nodes with raw pointers.
//! Here the nodes live in a single arena (`Vec<Node>`) and the links are arena
//! indices, with [`NIL`] standing in for a null pointer. Indices stay valid
//! across arena growth, which pointers into a `Vec` would not.

/// Sentinel used where the reference implementation stores a null `Node*`.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy)]
pub struct Node {
    /// Index of the vertex within the flattened input.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in a polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Self {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

