//! Geometric predicates over arena nodes.
//!
//! Every comparison here is performed on `f64` exactly as the reference
//! implementation does: no epsilons, no reordering of the arithmetic. The
//! triangulation of a self-intersecting ring is decided by the sign of these
//! expressions, so the operand order is load-bearing.

use super::node::NIL;
use super::Earcut;

impl Earcut {
    /// Signed area of the triangle `(p, q, r)`, doubled.
    pub(super) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
    }

    /// Check if two points are equal.
    pub(super) fn equals(&self, p1: usize, p2: usize) -> bool {
        let (p1, p2) = (&self.nodes[p1], &self.nodes[p2]);
        p1.x == p2.x && p1.y == p2.y
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
            && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
            && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    }

    /// `(0.0 < val) - (val < 0.0)`, i.e. the sign as -1, 0 or 1.
    pub(super) fn sign(val: f64) -> i32 {
        i32::from(0.0 < val) - i32::from(val < 0.0)
    }

    /// For collinear points `p`, `q`, `r`, check if point `q` lies on segment `pr`.
    pub(super) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
        q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
    }

    /// Check if two segments intersect.
    pub(super) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = Self::sign(self.area(p1, q1, p2));
        let o2 = Self::sign(self.area(p1, q1, q2));
        let o3 = Self::sign(self.area(p2, q2, p1));
        let o4 = Self::sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // p1, q1 and p2 are collinear and p2 lies on p1q1
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are collinear and q2 lies on p1q1
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are collinear and p1 lies on p2q2
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are collinear and q1 lies on p2q2
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// Check if a polygon diagonal intersects any polygon segment.
    pub(super) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let ai = self.nodes[a].i;
        let bi = self.nodes[b].i;
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != ai
                && self.nodes[pn].i != ai
                && self.nodes[p].i != bi
                && self.nodes[pn].i != bi
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                return false;
            }
        }
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    pub(super) fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// Check if the middle point of a polygon diagonal is inside the polygon.
    pub(super) fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (cur, nxt) = (&self.nodes[p], &self.nodes[pn]);
            if ((cur.y > py) != (nxt.y > py))
                && nxt.y != cur.y
                && (px < (nxt.x - cur.x) * (py - cur.y) / (nxt.y - cur.y) + cur.x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                return inside;
            }
        }
    }

    /// Check whether a diagonal between two polygon nodes lies within the polygon
    /// area, does not intersect other edges and does not create opposite-facing
    /// sectors.
    pub(super) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bi = self.nodes[b].i;
        let bp = self.nodes[b].prev;
        let bn = self.nodes[b].next;

        self.nodes[an].i != bi
            && self.nodes[ap].i != bi
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// Whether sector in vertex `m` contains the sector in vertex `p` in the same
    /// coordinates.
    pub(super) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        let mp = self.nodes[m].prev;
        let pn = self.nodes[p].next;
        self.area(mp, m, p) < 0.0 && self.area(pn, m, mp) < 0.0
    }

    /// Find the leftmost node of a polygon ring.
    pub(super) fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            let (np, nl) = (&self.nodes[p], &self.nodes[leftmost]);
            if np.x < nl.x || (np.x == nl.x && np.y < nl.y) {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                return leftmost;
            }
        }
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the same
    /// ring, it splits the polygon into two. If one belongs to the outer ring and
    /// another to a hole, it merges it into a single ring.
    pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = {
            let n = &self.nodes[a];
            (n.i, n.x, n.y)
        };
        let (bi, bx, by) = {
            let n = &self.nodes[b];
            (n.i, n.x, n.y)
        };
        let a2 = self.construct(ai, ax, ay);
        let b2 = self.construct(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Remove a node from both the vertex ring and the z-order list.
    pub(super) fn remove_node(&mut self, p: usize) {
        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

