        let mut leftmost = start;
        loop {
            let (np, nl) = (&self.nodes[p], &self.nodes[leftmost]);
            if np.x < nl.x || (np.x == nl.x && np.y < nl.y) {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                return leftmost;
            }
        }
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the same
    /// ring, it splits the polygon into two. If one belongs to the outer ring and
    /// another to a hole, it merges it into a single ring.
    pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = {
            let n = &self.nodes[a];
            (n.i, n.x, n.y)
        };
        let (bi, bx, by) = {
            let n = &self.nodes[b];
            (n.i, n.x, n.y)
        };
        let a2 = self.construct(ai, ax, ay);
        let b2 = self.construct(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Remove a node from both the vertex ring and the z-order list.
    pub(super) fn remove_node(&mut self, p: usize) {
        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

