//! Ear-clipping polygon triangulator.
//!
//! A `std`-only port of the `mapbox::earcut` 2.2.x algorithm: build a circular
//! doubly-linked list from the outer ring, splice holes in as bridges, then clip
//! ears one by one. When no ear can be found the algorithm escalates through
//! three fallbacks — filter collinear points, cure local self-intersections,
//! and finally split the ring on a valid diagonal — which is what makes a
//! self-intersecting input such as a spiral triangulable at all.
//!
//! The triangle indices are emitted in exactly the order the reference
//! implementation emits them; the fallback passes are order-sensitive, so the
//! control flow is kept structurally identical rather than idiomatically
//! restructured.

pub mod geom;
pub mod node;
pub mod zorder;

use node::{Node, NIL};

/// Triangulate a polygon given as a list of rings (outer ring first, holes after)
/// and return a flat list of triangle vertex indices into the concatenated rings.
pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut earcut = Earcut::new();
    earcut.run(points);
    earcut.indices
}

pub struct Earcut {
    pub indices: Vec<u32>,
    pub vertices: usize,

    /// Arena backing the linked list; `usize` indices replace the original `Node*`.
    pub(crate) nodes: Vec<Node>,

    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Allocate a node in the arena and return its index.
    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;
        self.nodes.clear();
        self.hashing = false;
        self.inv_size = 0.0;

        if points.is_empty() {
            return;
        }

        // The z-order hash only pays off past a vertex count threshold; the loop
        // stops early once the budget is blown, matching the reference exactly.
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                self.max_x = self.max_x.max(x);
                self.max_y = self.max_y.max(y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Create a circular doubly-linked list from polygon points in the specified
    /// winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let mut sum = 0.0;
        let len = points.len();
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            let p20 = p2[0];
            let p10 = p1[0];
            let p11 = p1[1];
            let p21 = p2[1];
            sum += (p20 - p10) * (p11 + p21);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, &points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, &points[i], last);
            }
        }

        if last != NIL {
            let next = self.nodes[last].next;
            if self.equals(last, next) {
                self.remove_node(last);
                last = next;
            }
        }

        self.vertices += len;

        last
    }

    /// Create a node and optionally link it with a previous one (in a circular
    /// doubly-linked list).
    fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
        let p = self.construct(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let next = self.nodes[last].next;
            self.nodes[p].next = next;
            self.nodes[p].prev = last;
            self.nodes[next].prev = p;
            self.nodes[last].next = p;
        }

        p
    }

    /// Eliminate colinear or duplicate points. Pass `NIL` for `end` to default it
    /// to `start`.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let again;
            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;

            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
                self.remove_node(p);
                p = prev;
                end = prev;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = next;
                again = false;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        let mut ear = ear;
        if ear == NIL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if found {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any
            // more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections
                    // locally
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[c].next;

        while p != a {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = pn;
        }

        true
    }

    /// Same as [`Earcut::is_ear`] but only visiting points whose z-order falls in
    /// the triangle's bounding box range.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NIL && self.nodes[p].z <= max_z {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if p != a
                && p != c
                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NIL && self.nodes[p].z >= min_z {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if p != a
                && p != c
                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;

        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved; `pn` is still `p.next` after the first
                // removal, which only rewires the neighbours
                self.remove_node(p);
                self.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let an = self.nodes[a].next;
            let mut b = self.nodes[an].next;

            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a2 = self.filter_points(a, a_next);
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, c_next);

                    // run earcut on each half
                    self.earcut_linked(a2, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                return;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        let mut queue: Vec<usize> = Vec::new();

        for ring in &points[1..] {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                let leftmost = self.get_leftmost(list);
                queue.push(leftmost);
            }
        }

        {
            let nodes = &self.nodes;
            queue.sort_by(|&a, &b| {
                nodes[a]
                    .x
                    .partial_cmp(&nodes[b].x)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
        }

        // process holes from left to right
        let mut outer_node = outer_node;
        for hole in queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring and
    /// link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, br_next);
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, b_next)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and an outer
    /// polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost vertex to
        // the left; segment's endpoint with lesser x will be potential connection
        // vertex
        loop {
            let pn = self.nodes[p].next;
            let (py, pny) = (self.nodes[p].y, self.nodes[pn].y);
            if hy <= py && hy >= pny && pny != py {
                let (px, pnx) = (self.nodes[p].x, self.nodes[pn].x);
                let x = px + (hy - py) / (pny - py) * (pnx - px);
                if x <= hx && x > qx {
                    qx = x;
                    m = if px < pnx { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole vertex, segment intersection
        // and endpoint; if there are no points found, we have a valid connection;
        // otherwise choose the vertex of the polygon with the least x
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = m;
        loop {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            if hx >= px
                && px >= mx
                && hx != px
                && self.point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan_cur = ((hy - py) / (hx - px)).abs(); // tangential

                if self.locally_inside(p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }
}

toolUseResult.content:
//! Ear-clipping polygon triangulator.
//!
//! A `std`-only port of the `mapbox::earcut` 2.2.x algorithm: build a circular
//! doubly-linked list from the outer ring, splice holes in as bridges, then clip
//! ears one by one. When no ear can be found the algorithm escalates through
//! three fallbacks — filter collinear points, cure local self-intersections,
//! and finally split the ring on a valid diagonal — which is what makes a
//! self-intersecting input such as a spiral triangulable at all.
//!
//! The triangle indices are emitted in exactly the order the reference
//! implementation emits them; the fallback passes are order-sensitive, so the
//! control flow is kept structurally identical rather than idiomatically
//! restructured.

pub mod geom;
pub mod node;
pub mod zorder;

use node::{Node, NIL};

/// Triangulate a polygon given as a list of rings (outer ring first, holes after)
/// and return a flat list of triangle vertex indices into the concatenated rings.
pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut earcut = Earcut::new();
    earcut.run(points);
    earcut.indices
}

pub struct Earcut {
    pub indices: Vec<u32>,
    pub vertices: usize,

    /// Arena backing the linked list; `usize` indices replace the original `Node*`.
    pub(crate) nodes: Vec<Node>,

    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Allocate a node in the arena and return its index.
    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;
        self.nodes.clear();
        self.hashing = false;
        self.inv_size = 0.0;

        if points.is_empty() {
            return;
        }

        // The z-order hash only pays off past a vertex count threshold; the loop
        // stops early once the budget is blown, matching the reference exactly.
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        // estimate size of nodes and indices
        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                self.max_x = self.max_x.max(x);
                self.max_y = self.max_y.max(y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Create a circular doubly-linked list from polygon points in the specified
    /// winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let mut sum = 0.0;
        let len = points.len();
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i];
            let p2 = &points[j];
            let p20 = p2[0];
            let p10 = p1[0];
            let p11 = p1[1];
            let p21 = p2[1];
            sum += (p20 - p10) * (p11 + p21);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, &points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, &points[i], last);
            }
        }

        if last != NIL {
            let next = self.nodes[last].next;
            if self.equals(last, next) {
                self.remove_node(last);
                last = next;
            }
        }

        self.vertices += len;

        last
    }

    /// Create a node and optionally link it with a previous one (in a circular
    /// doubly-linked list).
    fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
        let p = self.construct(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let next = self.nodes[last].next;
            self.nodes[p].next = next;
            self.nodes[p].prev = last;
            self.nodes[next].prev = p;
            self.nodes[last].next = p;
        }

        p
    }

    /// Eliminate colinear or duplicate points. Pass `NIL` for `end` to default it
    /// to `start`.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let again;
            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;

            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
                self.remove_node(p);
                p = prev;
                end = prev;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = next;
                again = false;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        let mut ear = ear;
        if ear == NIL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if found {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any
            // more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections
                    // locally
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[c].next;

        while p != a {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = pn;
        }

        true
    }

    /// Same as [`Earcut::is_ear`] but only visiting points whose z-order falls in
    /// the triangle's bounding box range.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NIL && self.nodes[p].z <= max_z {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if p != a
                && p != c
                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NIL && self.nodes[p].z >= min_z {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if p != a
                && p != c
                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(pp, p, pn) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;

        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved; `pn` is still `p.next` after the first
                // removal, which only rewires the neighbours
                self.remove_node(p);
                self.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let an = self.nodes[a].next;
            let mut b = self.nodes[an].next;

            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a2 = self.filter_points(a, a_next);
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, c_next);

                    // run earcut on each half
                    self.earcut_linked(a2, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                return;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        let mut queue: Vec<usize> = Vec::new();

        for ring in &points[1..] {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                let leftmost = self.get_leftmost(list);
                queue.push(leftmost);
            }
        }

        {
            let nodes = &self.nodes;
            queue.sort_by(|&a, &b| {
                nodes[a]
                    .x
                    .partial_cmp(&nodes[b].x)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
        }

        // process holes from left to right
        let mut outer_node = outer_node;
        for hole in queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring and
    /// link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, br_next);
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, b_next)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and an outer
    /// polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost vertex to
        // the left; segment's endpoint with lesser x will be potential connection
        // vertex
        loop {
            let pn = self.nodes[p].next;
            let (py, pny) = (self.nodes[p].y, self.nodes[pn].y);
            if hy <= py && hy >= pny && pny != py {
                let (px, pnx) = (self.nodes[p].x, self.nodes[pn].x);
                let x = px + (hy - py) / (pny - py) * (pnx - px);
                if x <= hx && x > qx {
                    qx = x;
                    m = if px < pnx { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole vertex, segment intersection
        // and endpoint; if there are no points found, we have a valid connection;
        // otherwise choose the vertex of the polygon with the least x
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = m;
        loop {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            if hx >= px
                && px >= mx
                && hx != px
                && self.point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan_cur = ((hy - py) / (hx - px)).abs(); // tangential

                if self.locally_inside(p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }
}

