//! Command-line argument handling matching the C runtime's `std::atoi`.

/// `std::atoi` semantics as implemented by glibc, i.e. `(int) strtol(s, NULL, 10)`:
///
/// * leading whitespace is skipped,
/// * an optional `+`/`-` sign is consumed,
/// * digits are consumed greedily and parsing stops at the first non-digit,
/// * input with no leading digits yields `0`,
/// * out-of-range values saturate at the `long` bounds and are then truncated to
///   `int`.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    // isspace(): space, \t, \n, \v, \f, \r
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let mut acc: i64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = i64::from(bytes[i] - b'0');
        match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
            Some(v) => acc = v,
            None => overflowed = true,
        }
        i += 1;
    }

    let long_value = if overflowed {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    long_value as i32
}

