//! Generation of the Archimedean spiral ring fed to the triangulator.

use std::f64::consts::PI;

/// Sample `2 * n` points of a spiral whose radius grows linearly with the
/// parameter `t` over two full turns.
///
/// The arithmetic mirrors the C++ source term by term — `t` is the integer ratio
/// `i / (n * 2)` and the angle is `(4.0 * PI) * t` — so the sampled coordinates
/// are bit-identical doubles.
pub fn spiral(n: i32) -> Vec<[f64; 2]> {
    let count = n.wrapping_mul(2);
    let mut points: Vec<[f64; 2]> = Vec::new();

    let mut i: i32 = 0;
    while i < count {
        let t = f64::from(i) / f64::from(count);
        let radius = t;
        let angle = 4.0 * PI * t;
        points.push([radius * angle.cos(), radius * angle.sin()]);
        i += 1;
    }

    points
}

